ruleContent.content:
@js:(function(){
try{
  var resultStr = result;

  if(typeof resultStr === 'undefined' || resultStr === null) return '';

  var json;
  if(typeof resultStr === 'object') {
    json = resultStr;
  } else {
    if(typeof resultStr !== 'string' || resultStr.length < 10) return '';
    try { json = JSON.parse(resultStr); } catch(e) { return ''; }
  }

  var info = json.data && json.data.info ? json.data.info : {};
  var imagesData = info.images;
  var NL = String.fromCharCode(10);
  var host = 'https://c-nc-1.6wm.top';

  if(imagesData && imagesData.images) {
    var imgs = imagesData.images;
    var isString = typeof imgs === 'string';

    if(!isString && typeof imgs === 'object' && typeof imgs.length === 'number') {
      if(imgs.length > 0 && typeof imgs[0] === 'string' && imgs[0].indexOf('J7r') === 0) {
        var joined = '';
        for(var _i = 0; _i < imgs.length; _i++) { joined += imgs[_i]; }
        imagesData = { images: joined, line: imagesData.line || 1 };
        isString = true;
      } else {
        var line = imagesData.line || 1;
        if(line === 2) host = 'https://c-nd2-1.6wm.top';
        else if(line === 3) host = 'https://c-nd3-1.6wm.top';
        var tags = [];
        for(var _j = 0; _j < imgs.length; _j++) {
          var u = imgs[_j];
          if(u && typeof u === 'object' && u.url) u = u.url;
          if(u && typeof u === 'string') {
            if(u.indexOf('http') !== 0) u = host + u;
            tags.push('<img src="' + u + '">');
          }
        }
        return tags.join(NL);
      }
    }

    if(isString) {
      var encrypted = imgs;
      var lineNum = imagesData.line || 1;

      if(encrypted.substring(0, 3) !== 'J7r' || encrypted.substring(encrypted.length - 2) !== 'nQ' || encrypted.length < 20) return '';

      var FROM_TABLE = '_-9876543210abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
      var TO_TABLE   = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
      var CHUNK_SIZE = 7;
      var MAGIC_A = 'kD';
      var MAGIC_B = 'W4s';

      var stripped = encrypted.substring(3, encrypted.length - 2);
      var dataLen = stripped.length;
      var K = Math.floor((dataLen - 5) / 3);

      var p1_len = K;
      var R = dataLen - K - 3;

      var markerFound = true;
      if(stripped.substring(p1_len, p1_len + 2) !== MAGIC_A) markerFound = false;
      if(stripped.substring(R, R + 3) !== MAGIC_B) markerFound = false;

      if(!markerFound) {
        var idxA = stripped.indexOf(MAGIC_A);
        var idxB = stripped.indexOf(MAGIC_B);
        if(idxA >= 0 && idxB > idxA + 2) {
          p1_len = idxA;
          R = idxB;
        } else { return ''; }
      }

      var p1 = stripped.substring(0, p1_len);
      var p3 = stripped.substring(p1_len + 2, R);
      var p5 = stripped.substring(R + 3);

      var pairSwap = function(str) {
        var out = '';
        var i = 0;
        var chunkIdx = 0;
        while(i < str.length) {
          var chunk = str.substring(i, i + CHUNK_SIZE);
          if(chunkIdx % 2 === 1) {
            var rev = '';
            for(var j = chunk.length - 1; j >= 0; j--) rev += chunk[j];
            chunk = rev;
          }
          out += chunk;
          i += CHUNK_SIZE;
          chunkIdx++;
        }
        return out;
      };

      var combined = pairSwap(p5 + p1 + p3);
      var substituted = '';
      for(var si = 0; si < combined.length; si++) {
        var c = combined.charAt(si);
        var idx = FROM_TABLE.indexOf(c);
        substituted += idx >= 0 ? TO_TABLE.charAt(idx) : c;
      }

      var b64 = substituted.replace(/-/g, '+').replace(/_/g, '/');
      while(b64.length % 4 !== 0) b64 += '=';

      var chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
      var decoded = '';
      for(var bi = 0; bi < b64.length; bi += 4) {
        if(b64.charAt(bi+1) === '') break;
        var c1 = chars.indexOf(b64.charAt(bi));
        var c2 = chars.indexOf(b64.charAt(bi+1));
        var c3 = chars.indexOf(b64.charAt(bi+2));
        var c4 = chars.indexOf(b64.charAt(bi+3));
        var triple = (c1 << 18) | (c2 << 12) | ((c3 & 63) << 6) | (c4 & 63);
        decoded += String.fromCharCode((triple >>> 16) & 255);
        if(c3 >= 0) decoded += String.fromCharCode((triple >>> 8) & 255);
        if(c4 >= 0) decoded += String.fromCharCode(triple & 255);
      }

      var imageList = JSON.parse(decoded);

      if(!imageList || typeof imageList !== 'object' || typeof imageList.length === 'undefined') return '';

      if(lineNum === 2) host = 'https://c-nd2-1.6wm.top';
      else if(lineNum === 3) host = 'https://c-nd3-1.6wm.top';

      var imgTags = [];
      for(var ti = 0; ti < imageList.length; ti++) {
        var item = imageList[ti];
        var url = item && (item.url || item);
        if(url && typeof url === 'string') {
          if(url.indexOf('http') !== 0) url = host + url;
          imgTags.push('<img src="' + url + '">');
        }
      }

      return imgTags.join(NL);
    }
  }

  return '';
} catch(e) {
  return '';
}
})()

